import {setupScene} from './scene.js';
import {createEngine,createReferenceEngine} from './engine.js';
import {MODEL,parameters,geometric,waveSample,normals} from './physics.js';
const $=id=>document.getElementById(id);
const defaults={lambda:550,slitWidth:.08,separation:.30,screenDistance:2.5};
let state={...defaults},mode='wave',paused=false,dirty=true,revision=0,engine=null,frame=null,elapsed=0,gpuVerified=false;
const waveTexture=document.createElement('canvas'),geoTexture=document.createElement('canvas'),screenTexture=document.createElement('canvas');
const scene=setupScene($('sceneCanvas'),()=>state,()=>screenTexture);
const methodText=`<div><h3>真实计算路径</h3><p>Wave Tracing 的单交互、标量近轴子集。每个样本从传感器发出最小不确定性高斯模式，沿保守椭圆锥传播到双缝，收集同一局部交互区域中的两个开口，计算完整复数重叠后取模平方。样本之间只累加非负功率。</p><p>本实现直接连接已知相干光源，使用局部 Fresnel 高斯模式重叠；没有 FFT，没有跨路径复振幅累加，也没有事后叠加条纹。</p></div><div><h3>明确的范围</h3><p>有限矩形双缝，高度 0.18 mm；单色相干高斯照明，强度标准差 0.7 mm；高斯传感器 σ = 0.035 mm。每段开口用 16 点 Gauss–Legendre 积分，5σ 尾部截断。</p><p>不包含反射器、多次反弹、UTD、偏振、有限厚度与非近轴 Maxwell 求解，也不是官方 C++ 渲染器的完整移植。</p></div><div><h3>验证与阅读</h3><p>独立的 Fresnel 场传播再做传感器卷积，与模式积分在 20 个二维测试点比较：含截断最大相对误差 0.0018%。这不是 GPU 实测性能或原生渲染器对照。</p><p>发布环境未能启动浏览器，GPU 与页面视觉验收尚未完成。本站在获得 WebGPU 后会执行编译诊断及 16 点 GPU/CPU 核对。<a href="method.html">完整推导、来源与验证边界 ↗</a></p></div>`;
$('methodContent').innerHTML=methodText;
$('heatmapRange').textContent='x: −12 … +12 mm · y: −7.5 … +7.5 mm';
$('regionNotice').textContent='传感器平面 24 × 15 mm。两模式分别按各自峰值归一化，只比较形状；热图为 −40 … 0 dB，非相同绝对亮度。';
for(const key of Object.keys(defaults)){$(key).addEventListener('input',()=>{state[key]=Number($(key).value);revision++;dirty=true;frame=null;elapsed=0;updateValues();clearResults();scene.draw();});}
function updateValues(){for(const key of Object.keys(defaults)){const v=state[key];$(key+'Value').textContent=key==='lambda'?v+' nm':v.toFixed(key==='screenDistance'?2:3)+(key==='screenDistance'?' m':' mm');}const p=parameters(state),f=(state.separation+state.slitWidth)**2/(p.wavelength*p.L);$('qualityNotice').textContent=`单交互近轴模型 · Fresnel 数 ${f.toFixed(3)} · σ₀ 35 μm · 16 点局部积分。数值样本相互独立；没有合成噪声。`;}
$('orbit').addEventListener('input',()=>{const n=Number($('orbit').value);$('orbitValue').textContent=n+'°';scene.setOrbit(n);});
for(const button of document.querySelectorAll('[data-mode]'))button.addEventListener('click',()=>{mode=button.dataset.mode;for(const b of document.querySelectorAll('[data-mode]')){const on=b===button;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));}render();});
function setPause(v){paused=v;$('pauseButton').innerHTML=`<span aria-hidden="true">${v?'▶':'Ⅱ'}</span><span>${v?'继续采样':'暂停采样'}</span>`;updateStatus();}
$('pauseButton').addEventListener('click',()=>setPause(!paused));
$('resetButton').addEventListener('click',()=>{state={...defaults};for(const k of Object.keys(defaults))$(k).value=state[k];$('orbit').value=0;$('orbitValue').textContent='0°';scene.resetCamera();revision++;dirty=true;frame=null;elapsed=0;setPause(false);updateValues();clearResults();});
function updateStatus(){if(!engine)return;$('backendBadge').textContent=engine.type;$('engineDot').style.background=engine.type==='WebGPU'?'#b9e0b2':'#e1b76d';$('status').textContent=(paused?'已暂停。':document.hidden?'页面在后台，采样已暂缓。':'正在渐进采样。')+(engine.type==='WebGPU'?(gpuVerified?'GPU/CPU 16 点核对通过。':'WebGPU 内置核对待运行。'):'当前为 CPU 参考模式，未使用 GPU。');}
function clearResults(){for(const id of ['heatmapCanvas','profileCanvas']){const c=$(id),ctx=c.getContext('2d');ctx.fillStyle='#0c1612';ctx.fillRect(0,0,c.width,c.height);}for(const c of [waveTexture,geoTexture,screenTexture]){c.width=160;c.height=96;c.getContext('2d').clearRect(0,0,160,96);}$('spp').textContent='0';$('elapsed').textContent='0.0 s';}
function paintTexture(canvas,data,w,h,column,scale){canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d'),im=ctx.createImageData(w,h);for(let i=0;i<w*h;i++){const v=column===0?data[4*i]/Math.max(1,data[4*i+3]):data[4*i+2];let t=Math.max(0,Math.min(1,(10*Math.log10(Math.max(v/scale,1e-4))+40)/40));t=Math.pow(t,1.5);im.data[4*i]=Math.round(9+210*t);im.data[4*i+1]=Math.round(21+218*t);im.data[4*i+2]=Math.round(16+174*t);im.data[4*i+3]=255;}ctx.putImageData(im,0,0);}
function sizeCanvas(c,height){const dpr=Math.min(devicePixelRatio||1,2),w=Math.max(200,c.getBoundingClientRect().width);if(c.width!==Math.round(w*dpr)||c.height!==Math.round(height*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(height*dpr);}const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return {ctx,w,h:height};}
function render(){if(!frame||!engine){scene.draw();return;}const {data}=frame,w=engine.width,h=engine.height;let maxW=1e-20,maxG=1e-20;for(let i=0;i<w*h;i++){maxW=Math.max(maxW,data[4*i]/data[4*i+3]);maxG=Math.max(maxG,data[4*i+2]);}paintTexture(waveTexture,data,w,h,0,maxW);paintTexture(geoTexture,data,w,h,2,maxG);
 const out=$('heatmapCanvas'),a=sizeCanvas(out,220),ctx=a.ctx;ctx.fillStyle='#09110d';ctx.fillRect(0,0,a.w,a.h);ctx.imageSmoothingEnabled=true;
 if(mode==='split'){const half=a.w/2;ctx.drawImage(waveTexture,0,0,half-3,a.h);ctx.drawImage(geoTexture,half+3,0,half-3,a.h);ctx.fillStyle='#eef6eb';ctx.font='12px system-ui';ctx.fillText('波动 · 各自峰值',10,20);ctx.fillText('几何 · 各自峰值',half+13,20);}else ctx.drawImage(mode==='wave'?waveTexture:geoTexture,0,0,a.w,a.h);
 $('heatmapTitle').textContent=mode==='split'?'并排显示完整同一视野':mode==='wave'?'高斯锥追踪 · 相对光强':'几何传播 · 相对光强';
 screenTexture.width=w;screenTexture.height=h;screenTexture.getContext('2d').drawImage(mode==='geometric'?geoTexture:waveTexture,0,0);
 const plot=sizeCanvas($('profileCanvas'),190),pc=plot.ctx;pc.clearRect(0,0,plot.w,plot.h);const m={l:42,r:14,t:12,b:32},pw=plot.w-m.l-m.r,ph=plot.h-m.t-m.b;pc.font='11px system-ui';pc.fillStyle='#90a696';pc.strokeStyle='#2a3b30';pc.lineWidth=1;for(let v=0;v<=1;v+=.25){const y=m.t+(1-v)*ph;pc.beginPath();pc.moveTo(m.l,y);pc.lineTo(plot.w-m.r,y);pc.stroke();pc.fillText(v.toFixed(2),3,y+4);}for(const x of [-12,-6,0,6,12]){pc.fillText(x.toString(),m.l+(x/24+.5)*pw-6,plot.h-10);}pc.fillText('mm',plot.w-24,plot.h-10);
 const row=Math.floor(h/2);let lineMaxW=1e-20;for(let x=0;x<w;x++)lineMaxW=Math.max(lineMaxW,data[4*(row*w+x)]/data[4*(row*w+x)+3]);
 function line(color,fn,n){pc.strokeStyle=color;pc.lineWidth=1.6;pc.beginPath();for(let j=0;j<n;j++){const x=m.l+j/(n-1)*pw,y=m.t+(1-fn(j))*ph;if(j===0)pc.moveTo(x,y);else pc.lineTo(x,y);}pc.stroke();}
 if(mode!=='geometric')line('#b9e0b2',x=>data[4*(row*w+x)]/data[4*(row*w+x)+3]/lineMaxW,w);
 if(mode!=='wave'){const p=parameters(state),n=960,values=Array.from({length:n},(_,i)=>geometric((i/(n-1)-.5)*24,0,p)),max=Math.max(...values);line('#e4b77c',i=>values[i]/max,n);}
 $('waveLegend').style.opacity=mode==='geometric'?'.25':'1';$('geometricLegend').style.opacity=mode==='wave'?'.25':'1';scene.draw();}
function verifyGPU(result){const p=parameters(state),w=engine.width,h=engine.height,indices=[0,Math.floor(h/3),Math.floor(h/2),h-1].flatMap(y=>[0,Math.floor(w/3),Math.floor(w/2),w-1].map(x=>y*w+x));let worst=0,peak=0;const refs=[];for(const i of indices){const X=((i%w+.5)/w-.5)*MODEL.spanX,Y=((Math.floor(i/w)+.5)/h-.5)*MODEL.spanY;let expected=0;for(let s=0;s<result.spp;s++){const [a,b]=normals(i,s);expected+=waveSample(X,Y,a,b,p);}refs.push([result.data[i*4],expected]);peak=Math.max(peak,expected);}for(const [got,expected]of refs){const error=Math.abs(got-expected)/(peak*3e-5+Math.abs(expected)*.003+1e-15);if(!Number.isFinite(got)||error>1)throw new Error('GPU/CPU 核对未通过，已停止 GPU 结果显示。');worst=Math.max(worst,error);}gpuVerified=true;globalThis.waveLabValidation={gpuCpuParity:true,points:16,normalizedToleranceRatio:worst};}
async function fallback(reason){revision++;frame=null;elapsed=0;engine=createReferenceEngine();clearResults();gpuVerified=false;dirty=true;$('qualityNotice').textContent=`${reason}。已明确切换到低分辨率 CPU 参考模式；数值方法相同，计算全部在本浏览器中。`;$('backendBadge').title=reason;updateStatus();}
async function loop(){if(engine&&!paused&&!document.hidden){const rev=revision;if(dirty){engine.reset();dirty=false;elapsed=0;gpuVerified=false;}const t=performance.now();try{const activeEngine=engine;const result=await activeEngine.step(state,activeEngine.type==='WebGPU'?4:1);if(rev===revision){if(engine.type==='WebGPU'&&!gpuVerified)verifyGPU(result);elapsed+=(performance.now()-t)/1000;frame=result;$('spp').textContent=result.spp.toLocaleString();$('elapsed').textContent=elapsed.toFixed(1)+' s';render();updateStatus();}}catch(error){await fallback(error.message||String(error));}}requestAnimationFrame(loop);}
window.addEventListener('resize',()=>render());document.addEventListener('visibilitychange',updateStatus);
updateValues();clearResults();scene.draw();
try{engine=await createEngine(160,96,msg=>{if(engine?.type==='WebGPU')fallback(msg);});updateStatus();}catch(e){await fallback(e.message||String(e));}
requestAnimationFrame(loop);
globalThis.waveLab={getState:()=>({...state,mode,paused,spp:frame?.spp||0,backend:engine?.type,gpuVerified}),waveSample,parameters};
